/* ----------------------------------------------------------------------
   DESIGN TOKENS
   Paper white / near-black ink / weld-spark amber — with a dark-mode
   counterpart (charcoal metal / same amber, brightened for contrast).
   Display face: condensed industrial caps (stencil-adjacent) for headers.
   Body: clean grotesk. Data face: mono, for anything measured (%, ms, mm).

   TOKENS is intentionally a mutable object rather than React state: every
   component below reads TOKENS.xxx at render time inside inline styles.
   Toggling theme mutates its values then bumps a state counter in the
   root component to force a re-render — no context plumbing needed.
---------------------------------------------------------------------- */
const LIGHT_TOKENS = {
  bg: "#FAFAF7",
  panel: "#FFFFFF",
  ink: "#15130F",
  inkSoft: "#6B6558",
  line: "#E7E2D6",
  amber: "#BA7517",
  amberDeep: "#8A5710",
  amberSoft: "#F3E4CC",
  good: "#3F6B4A",
  goodSoft: "#E4EDE5",
  bad: "#A23B2E",
  badSoft: "#F5E3E0",
};

const DARK_TOKENS = {
  bg: "#0B0F0D",
  panel: "rgba(24, 32, 28, 0.72)",
  ink: "#EDF3EE",
  inkSoft: "#8FA098",
  line: "rgba(255,255,255,0.08)",
  amber: "#E0A346",
  amberDeep: "#F2BE6E",
  amberSoft: "rgba(224,163,70,0.14)",
  good: "#5FDB8C",
  goodSoft: "rgba(95,219,140,0.12)",
  bad: "#E38A7A",
  badSoft: "rgba(227,138,122,0.14)",
};

const TOKENS = { ...LIGHT_TOKENS };
function applyTheme(mode) {
  Object.assign(TOKENS, mode === "dark" ? DARK_TOKENS : LIGHT_TOKENS);
}

