// 백엔드(Postgres에 저장된 실제 검사 기록)에서 날짜 범위로 가져옴 — 실패하면 빈 배열로 조용히 넘어감
async function fetchInspections(startStr, endStr) {
  try {
    const res = await fetch(`${INFERENCE_API}/inspections?start_date=${startStr}&end_date=${endStr}`);
    if (!res.ok) return [];
    return await res.json();
  } catch {
    return [];
  }
}

// 오탐/잘못 찍힌 검사 기록을 DB에서 완전히 지움 — 이후 대시보드/검사 상세/리포트 전부 이 기록을 다시 안 보게 됨
async function deleteInspectionRecord(id) {
  try {
    const res = await fetch(`${INFERENCE_API}/inspections/${id}`, { method: "DELETE" });
    return res.ok;
  } catch {
    return false;
  }
}

// toISOString()은 UTC 기준이라 한국 시간(KST, UTC+9)이랑 최대 9시간 어긋남.
// 화면에 보여줄 날짜/시각은 전부 기기의 로컬 시간 기준으로 만들어야 정확함.
function localDateStr(d) {
  const y = d.getFullYear(), m = String(d.getMonth() + 1).padStart(2, "0"), day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}
function localDateTimeStr(d) {
  const hh = String(d.getHours()).padStart(2, "0"), mm = String(d.getMinutes()).padStart(2, "0"), ss = String(d.getSeconds()).padStart(2, "0");
  return `${localDateStr(d)}T${hh}:${mm}:${ss}`;
}

const today = localDateStr(new Date());

function addDaysStr(dateStr, delta) {
  const d = new Date(dateStr + "T00:00:00");
  d.setDate(d.getDate() + delta);
  return localDateStr(d);
}
function dateRangeArray(startStr, endStr) {
  const out = [];
  let cur = startStr;
  let guard = 0;
  while (cur <= endStr && guard < 366) {
    out.push(cur);
    cur = addDaysStr(cur, 1);
    guard++;
  }
  return out;
}
const DEFAULT_START = addDaysStr(today, -6);

