/* ---------------------------- Bounding-box viewer (signature element) ----------------------------
   A camera-focus / HUD-style bracketed frame rather than a plain <img>+rect —
   ties the visual language back to "the moment of inspection." */
function InspectionFrame({ record }) {
  const { bbox, ai_judgment, image_data_uri } = record;
  const color = ai_judgment === "bad" ? TOKENS.bad : TOKENS.good;
  return (
    <div style={{
      position: "relative", width: "100%", aspectRatio: "4 / 3", borderRadius: 4,
      overflow: "hidden", background: image_data_uri ? "#000" :
        "repeating-linear-gradient(135deg, #2a2620 0px, #2a2620 2px, #322d24 2px, #322d24 4px)",
      border: `1px solid ${TOKENS.line}`,
    }}>
      {image_data_uri ? (
        <img src={image_data_uri} alt="캠 캡처 이미지" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
      ) : (
        <div style={{
          position: "absolute", inset: 0,
          background: "radial-gradient(ellipse at 40% 35%, #4a443a 0%, #201d18 70%)",
        }} />
      )}
      <svg viewBox="0 0 100 75" style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}>
        <defs>
          <filter id="grain"><feTurbulence baseFrequency="0.9" numOctaves="2" /></filter>
        </defs>
        {!image_data_uri && <rect width="100" height="75" filter="url(#grain)" opacity="0.06" />}
        {/* bbox */}
        <g>
          <rect
            x={bbox.x} y={bbox.y} width={bbox.w} height={bbox.h}
            fill="none" stroke={color} strokeWidth="0.6"
          />
          {/* corner brackets */}
          {[[bbox.x, bbox.y, 1, 1], [bbox.x + bbox.w, bbox.y, -1, 1],
            [bbox.x, bbox.y + bbox.h, 1, -1], [bbox.x + bbox.w, bbox.y + bbox.h, -1, -1]]
            .map(([cx, cy, dx, dy], i) => (
              <path key={i} d={`M ${cx} ${cy + dy * 6} L ${cx} ${cy} L ${cx + dx * 6} ${cy}`}
                stroke={color} strokeWidth="1.3" fill="none" />
            ))}
        </g>
      </svg>
      <div style={{
        position: "absolute", top: 10, left: 10, display: "flex", gap: 8, alignItems: "center",
      }}>
        <JudgmentBadge value={ai_judgment} />
        {image_data_uri && (
          <span style={{
            fontSize: 10, fontFamily: "'JetBrains Mono'", padding: "2px 7px", borderRadius: 3,
            background: "rgba(21,19,15,0.6)", color: "#EFE9DC", letterSpacing: "0.04em",
          }}>실시간 캠</span>
        )}
      </div>
      <div style={{
        position: "absolute", bottom: 10, right: 12,
        fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: "#EFE9DC",
        background: "rgba(21,19,15,0.55)", padding: "3px 8px", borderRadius: 3,
        letterSpacing: "0.04em",
      }}>{record.id}</div>
    </div>
  );
}

