function DateRangeSelector({ startDate, endDate, setStartDate, setEndDate }) {
  const presets = [
    { label: "최근 7일", start: addDaysStr(today, -6), end: today },
    { label: "최근 14일", start: addDaysStr(today, -13), end: today },
    { label: "오늘만", start: today, end: today },
  ];

  const handleStartChange = (v) => {
    setStartDate(v);
    // 시작일이 종료일보다 늦어지면(하루만 보고 싶은 경우 등) 종료일을 시작일로 맞춰줌
    if (v > endDate) setEndDate(v);
  };
  const handleEndChange = (v) => {
    if (v < startDate) return; // 시작일보다 이전으로는 못 감
    setEndDate(v);
  };

  const isSingleDay = startDate === endDate;

  return (
    <div style={{
      display: "flex", alignItems: "center", gap: 14, flexWrap: "wrap",
      background: TOKENS.panel, border: `1px solid ${TOKENS.line}`, borderRadius: 8,
      padding: "12px 16px", backdropFilter: "blur(14px)",
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 6, color: TOKENS.inkSoft, fontSize: 12 }}>
        <CalendarDays size={14} /> 조회 기간
      </div>

      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 6, border: `1px solid ${TOKENS.line}`, borderRadius: 5, padding: "6px 10px", background: TOKENS.bg }}>
          <CalendarDays size={14} color={TOKENS.inkSoft} />
          <input type="date" value={startDate} max={today} onChange={e => handleStartChange(e.target.value)} style={{
            border: "none", outline: "none", fontFamily: "'JetBrains Mono'", fontSize: 12.5, background: "transparent", color: TOKENS.ink,
          }} />
        </div>
        <span style={{ color: TOKENS.inkSoft, fontSize: 12 }}>부터</span>
        <div style={{ display: "flex", alignItems: "center", gap: 6, border: `1px solid ${TOKENS.line}`, borderRadius: 5, padding: "6px 10px", background: TOKENS.bg }}>
          <CalendarDays size={14} color={TOKENS.inkSoft} />
          <input type="date" value={endDate} min={startDate} max={today} onChange={e => handleEndChange(e.target.value)} style={{
            border: "none", outline: "none", fontFamily: "'JetBrains Mono'", fontSize: 12.5, background: "transparent", color: TOKENS.ink,
          }} />
        </div>
        <span style={{ color: TOKENS.inkSoft, fontSize: 12 }}>까지</span>
      </div>

      {isSingleDay && (
        <span style={{
          fontSize: 10.5, fontWeight: 600, color: TOKENS.amberDeep, background: TOKENS.amberSoft,
          padding: "3px 8px", borderRadius: 3,
        }}>하루만 조회중</span>
      )}

      <div style={{ display: "flex", gap: 6, marginLeft: "auto" }}>
        {presets.map(p => (
          <button key={p.label} onClick={() => { setStartDate(p.start); setEndDate(p.end); }} style={{
            padding: "6px 12px", borderRadius: 5, border: `1px solid ${TOKENS.line}`,
            background: (startDate === p.start && endDate === p.end) ? TOKENS.ink : "transparent",
            color: (startDate === p.start && endDate === p.end) ? TOKENS.bg : TOKENS.inkSoft,
            fontSize: 11.5, cursor: "pointer",
          }}>{p.label}</button>
        ))}
      </div>
    </div>
  );
}

