/* ---------------------------------- Gauge card (dribbble-style semicircle gauge) ----------------------------------
   Semicircle arc simply fills proportionally to this class's share of the
   selected period's total inspections — no target/planned value anymore. */
function polar(cx, cy, r, t) {
  const angle = Math.PI * (1 - t); // t=0 -> left(π), t=1 -> right(0)
  return { x: cx + r * Math.cos(angle), y: cy - r * Math.sin(angle) };
}
function arcPath(cx, cy, r, t0, t1) {
  const p0 = polar(cx, cy, r, t0);
  const p1 = polar(cx, cy, r, t1);
  const largeArc = t1 - t0 > 0.999 ? 1 : 0;
  return `M ${p0.x} ${p0.y} A ${r} ${r} 0 ${largeArc} 1 ${p1.x} ${p1.y}`;
}

function GaugeCard({ label, count, total, color }) {
  const t = total ? Math.min(count / total, 0.999) : 0;
  const cx = 90, cy = 86, r = 70, stroke = 14;

  return (
    <div style={{
      background: TOKENS.panel, border: `1px solid ${TOKENS.line}`, borderRadius: 10, padding: "18px 16px 16px",
      backdropFilter: "blur(14px)", display: "flex", flexDirection: "column", height: "100%",
    }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 7, marginBottom: 4 }}>
        <span style={{ width: 8, height: 8, borderRadius: 2, background: color, flexShrink: 0 }} />
        <span style={{ fontSize: 13, fontWeight: 600, color: TOKENS.ink }}>{label}</span>
      </div>
      <svg viewBox="0 0 180 105" style={{ width: "100%", height: "100%", display: "block", flex: 1 }}>
        <path d={arcPath(cx, cy, r, 0, 0.999)} fill="none" stroke={TOKENS.line} strokeWidth={stroke} strokeLinecap="round" />
        <path d={arcPath(cx, cy, r, 0, t)} fill="none" stroke={color} strokeWidth={stroke} strokeLinecap="round" />
        <text x={cx} y={cy - 8} textAnchor="middle" fontFamily="'JetBrains Mono', monospace" fontSize="32" fontWeight="700" fill={TOKENS.ink}>
          {count}
        </text>
        <text x={cx} y={cy + 15} textAnchor="middle" fontFamily="'JetBrains Mono', monospace" fontSize="12.5" fill={TOKENS.inkSoft}>
          건 ({total ? Math.round((count / total) * 100) : 0}%)
        </text>
      </svg>
    </div>
  );
}

