function RecentInspectionsTable({ data }) {
  const [page, setPage] = useState(1);
  const pageSize = 8;
  const sorted = useMemo(() => [...data].sort((a, b) => b.timestamp.localeCompare(a.timestamp)), [data]);
  const totalPages = Math.ceil(sorted.length / pageSize);
  const start = (page - 1) * pageSize;
  const rows = sorted.slice(start, start + pageSize);

  return (
    <div style={{ background: TOKENS.panel, border: `1px solid ${TOKENS.line}`, borderRadius: 6, overflow: "hidden", marginTop: 16 }}>
      <div style={{ padding: "16px 18px 4px" }}><Eyebrow>최근 검사 내역</Eyebrow></div>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5, fontFamily: "'Inter'" }}>
        <thead>
          <tr style={{ textAlign: "left" }}>
            {["일시", "ID", "AI 판정", "결함 유형", "신뢰도", "처리속도"].map(h => (
              <th key={h} style={{ padding: "8px 14px", fontSize: 11, color: TOKENS.inkSoft, borderBottom: `1px solid ${TOKENS.line}` }}>{h}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map(r => (
              <tr key={r.id} style={{ borderBottom: `1px solid ${TOKENS.line}` }}>
                <td style={{ padding: "8px 14px", fontFamily: "'JetBrains Mono'", fontSize: 11.5, color: TOKENS.inkSoft }}>{r.timestamp.slice(5, 10)} {r.timestamp.slice(11, 16)}</td>
                <td style={{ padding: "8px 14px", fontFamily: "'JetBrains Mono'", fontSize: 11.5 }}>{r.id}</td>
                <td style={{ padding: "8px 14px" }}><JudgmentBadge value={r.ai_judgment} size="sm" /></td>
                <td style={{ padding: "8px 14px", color: r.defect_type ? TOKENS.bad : TOKENS.good }}>{r.defect_type || "정상"}</td>
                <td style={{ padding: "8px 14px", fontFamily: "'JetBrains Mono'" }}>{(r.confidence * 100).toFixed(0)}%</td>
                <td style={{ padding: "8px 14px", fontFamily: "'JetBrains Mono'" }}>{r.processing_time_ms}ms</td>
              </tr>
          ))}
        </tbody>
      </table>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "12px 16px", borderTop: `1px solid ${TOKENS.line}` }}>
        <span style={{ fontSize: 12, color: TOKENS.inkSoft }}>{start + 1}-{Math.min(start + pageSize, data.length)} / 총 {data.length}건</span>
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1} style={{
            padding: "6px 12px", borderRadius: 5, border: `1px solid ${TOKENS.line}`, background: TOKENS.panel,
            fontSize: 12, cursor: page === 1 ? "default" : "pointer", opacity: page === 1 ? 0.4 : 1,
          }}>이전</button>
          <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages} style={{
            padding: "6px 12px", borderRadius: 5, border: `1px solid ${TOKENS.line}`, background: TOKENS.panel,
            fontSize: 12, cursor: page === totalPages ? "default" : "pointer", opacity: page === totalPages ? 0.4 : 1,
          }}>다음</button>
        </div>
      </div>
    </div>
  );
}

