function InspectionTab({ data, onDelete }) {
  const [selectedSession, setSelectedSession] = useState(null);

  // 날짜(session_id)별로 폴더 묶기 — 같은 날 자동 분류를 여러 번 시작/중지해도 그 날짜 폴더로 계속 이어서 쌓임. 오래된 폴더가 위, 최신 폴더가 아래
  const sessions = useMemo(() => {
    const map = {};
    data.forEach(d => {
      const key = d.session_id || d.timestamp;
      if (!map[key]) map[key] = [];
      map[key].push(d);
    });
    return Object.entries(map)
      .map(([sessionId, items]) => ({ sessionId, items }))
      .sort((a, b) => a.sessionId.localeCompare(b.sessionId));
  }, [data]);

  if (!selectedSession) {
    return <SessionFolderList sessions={sessions} onOpen={setSelectedSession} />;
  }

  const session = sessions.find(s => s.sessionId === selectedSession);
  const sessionItems = session ? session.items : [];

  return (
    <InspectionSessionDetail
      sessionId={selectedSession}
      items={sessionItems}
      onBack={() => setSelectedSession(null)}
      onDelete={onDelete}
    />
  );
}

function InspectionSessionDetail({ sessionId, items, onBack, onDelete }) {
  // 오래된 캡처가 위, 최신 캡처가 아래로 쌓이도록 정렬
  const sortedAsc = useMemo(() => [...items].sort((a, b) => a.timestamp.localeCompare(b.timestamp)), [items]);
  const [selectedId, setSelectedId] = useState(sortedAsc[sortedAsc.length - 1]?.id);
  const [deleting, setDeleting] = useState(false);
  const baseRecord = items.find(d => d.id === selectedId) || items[0];

  // 마지막 남은 기록까지 삭제하면 폴더 안에 볼 게 없으니 자동으로 폴더 목록으로 돌아감
  useEffect(() => {
    if (items.length === 0) onBack();
  }, [items.length]);

  const handleDelete = async () => {
    if (!baseRecord) return;
    if (!window.confirm(`이 검사 기록을 삭제할까요? (${baseRecord.id})\n삭제하면 리포트에서도 제외됩니다.`)) return;
    setDeleting(true);
    const ok = await onDelete(baseRecord.id);
    setDeleting(false);
    if (!ok) {
      window.alert("삭제에 실패했습니다. 백엔드 서버 상태를 확인해주세요.");
      return;
    }
    const idx = sortedAsc.findIndex(d => d.id === baseRecord.id);
    const next = sortedAsc[idx + 1] || sortedAsc[idx - 1];
    setSelectedId(next?.id);
  };

  return (
    <div>
      <SectionTitle>검사 상세</SectionTitle>

      <button onClick={onBack} style={{
        display: "flex", alignItems: "center", gap: 5, padding: "6px 10px", borderRadius: 5,
        border: `1px solid ${TOKENS.line}`, background: TOKENS.panel, color: TOKENS.inkSoft,
        fontSize: 12, cursor: "pointer", marginBottom: 16,
      }}>← 폴더 목록</button>

      {!baseRecord ? (
        <div style={{ color: TOKENS.inkSoft, fontSize: 13 }}>표시할 검사 기록 없음.</div>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "280px 1fr 300px", gap: 16 }}>

          {/* left: 검사 목록 (오래된 것 위 → 최신 것 아래) */}
          <InspectionList items={sortedAsc} selectedId={selectedId} setSelectedId={setSelectedId} />

          {/* center: frame */}
          <div>
            <InspectionFrame record={baseRecord} />
            <div style={{ display: "flex", gap: 12, marginTop: 12 }}>
              <div style={{ flex: 1, background: TOKENS.panel, border: `1px solid ${TOKENS.line}`, borderRadius: 6, padding: "12px 14px" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 6, color: TOKENS.inkSoft, fontSize: 11.5, marginBottom: 4 }}>
                  <Gauge size={13} /> 신뢰도
                </div>
                <div style={{ height: 6, background: TOKENS.line, borderRadius: 3, overflow: "hidden" }}>
                  <div style={{ width: `${baseRecord.confidence * 100}%`, height: "100%", background: TOKENS.amber }} />
                </div>
                <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 13, marginTop: 6 }}>{(baseRecord.confidence * 100).toFixed(1)}%</div>
              </div>
              <div style={{ flex: 1, background: TOKENS.panel, border: `1px solid ${TOKENS.line}`, borderRadius: 6, padding: "12px 14px" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 6, color: TOKENS.inkSoft, fontSize: 11.5, marginBottom: 4 }}>
                  <Clock size={13} /> 처리속도
                </div>
                <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 20, fontWeight: 600 }}>{baseRecord.processing_time_ms}<span style={{ fontSize: 12, color: TOKENS.inkSoft }}> ms</span></div>
              </div>
            </div>
          </div>

          {/* right: AI 판정 상세 */}
          <div style={{ background: TOKENS.panel, border: `1px solid ${TOKENS.line}`, borderRadius: 6, padding: 18 }}>
            <Eyebrow>AI 판정</Eyebrow>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
              <JudgmentBadge value={baseRecord.ai_judgment} size="sm" />
              <span style={{ fontSize: 11, color: TOKENS.inkSoft }}>{baseRecord.defect_type || "정상"} · {(baseRecord.confidence * 100).toFixed(0)}%</span>
            </div>

            <div style={{ marginTop: 16 }}>
              <Eyebrow>검사 정보</Eyebrow>
              <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 12.5, lineHeight: 2 }}>
                <div style={{ display: "grid", gridTemplateColumns: "88px 1fr" }}>
                  <span style={{ color: TOKENS.inkSoft }}>검사 ID</span>
                  <span>- {baseRecord.id}</span>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "88px 1fr" }}>
                  <span style={{ color: TOKENS.inkSoft }}>AI 결함 유형</span>
                  <span>- {baseRecord.defect_type || "정상"}</span>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "88px 1fr" }}>
                  <span style={{ color: TOKENS.inkSoft }}>검사 시각</span>
                  <span>- {baseRecord.timestamp.slice(0, 10)} {baseRecord.timestamp.slice(11, 16)}</span>
                </div>
              </div>
            </div>

            <button onClick={handleDelete} disabled={deleting} style={{
              display: "flex", alignItems: "center", justifyContent: "center", gap: 6, width: "100%",
              marginTop: 18, padding: "9px 0", borderRadius: 6, border: `1px solid ${TOKENS.bad}`,
              background: "transparent", color: TOKENS.bad, fontSize: 12.5, fontWeight: 600,
              cursor: deleting ? "default" : "pointer", opacity: deleting ? 0.6 : 1,
            }}>
              <Trash2 size={14} /> {deleting ? "삭제 중..." : "오탐 기록 삭제"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/* ---------------------------------- Reports tab (export logic) ---------------------------------- */

function toCSV(rows) {
  const headers = ["id", "part", "ai_judgment", "defect_type", "confidence", "processing_time_ms", "timestamp"];
  // UTF-8 BOM — 없으면 윈도우 엑셀로 더블클릭해서 열었을 때 한글(부품명/결함유형)이 깨져 보임
  const lines = ["﻿" + headers.join(",")];
  rows.forEach(r => {
    lines.push(headers.map(h => `"${(r[h] ?? "").toString().replace(/"/g, '""')}"`).join(","));
  });
  return lines.join("\n");
}

function downloadBlob(content, filename, mime) {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function computeReportSummary(rows) {
  const total = rows.length;
  const bad = rows.filter(r => r.ai_judgment === "bad").length;
  const good = total - bad;
  const avgMs = total ? Math.round(rows.reduce((s, r) => s + r.processing_time_ms, 0) / total) : 0;
  const defectCounts = {};
  rows.forEach(r => { if (r.defect_type) defectCounts[r.defect_type] = (defectCounts[r.defect_type] || 0) + 1; });
  const byType = DEFECT_TYPES.map(t => ({ type: t, count: defectCounts[t] || 0 }));
  byType.push({ type: "정상", count: good });
  return { total, bad, good, avgMs, byType };
}

function exportExcel(rows, dateStr) {
  const summary = computeReportSummary(rows);

  const summarySheetData = [
    ["두정테크 용접 불량 검출 리포트"],
    ["대상 날짜", dateStr],
    [],
    ["항목", "값"],
    ["총 검사 수", summary.total],
    ["정상", summary.good],
    ["불량", summary.bad],
    ["평균 처리속도(ms)", summary.avgMs],
    [],
    ["결함 유형", "건수"],
    ...summary.byType.map(b => [b.type, b.count]),
  ];
  const wsSummary = XLSX.utils.aoa_to_sheet(summarySheetData);
  wsSummary["!cols"] = [{ wch: 20 }, { wch: 14 }];

  const wsDetail = XLSX.utils.json_to_sheet(rows.map(r => ({
    ID: r.id, 판정: r.ai_judgment, 결함유형: r.defect_type || "정상",
    신뢰도: (r.confidence * 100).toFixed(1) + "%",
    처리속도_ms: r.processing_time_ms, 시각: r.timestamp,
  })));

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, wsSummary, "요약");
  XLSX.utils.book_append_sheet(wb, wsDetail, "상세");
  XLSX.writeFile(wb, `두정테크_검사리포트_${dateStr}.xlsx`);
}

// 실제 .pdf 파일로 바로 다운로드되도록 구현. 리포트를 화면 밖 임시 DOM에 그린 뒤
// html2canvas로 캡처하고, jsPDF로 A4 페이지(들)에 나눠 붙여서 save() — 인쇄 대화상자 없이 한 번에 받아짐.
async function exportPDF(rows, dateStr) {
  const s = computeReportSummary(rows);
  const defectRows = s.byType.map(b => `<tr><td>${b.type}</td><td>${b.count}건</td></tr>`).join("");
  const detailRows = rows.map(r => `
    <tr>
      <td>${r.id}</td>
      <td>${r.ai_judgment === "bad" ? "불량" : "정상"}</td>
      <td>${r.defect_type || "-"}</td>
      <td>${(r.confidence * 100).toFixed(0)}%</td>
      <td>${r.processing_time_ms}ms</td>
      <td>${r.timestamp.slice(11, 16)}</td>
    </tr>`).join("");

  const container = document.createElement("div");
  container.style.cssText = "position:fixed; left:-9999px; top:0; width:780px; background:#fff; padding:36px; font-family:'Malgun Gothic','Apple SD Gothic Neo',sans-serif; color:#15130F;";
  container.innerHTML = `
    <style>
      * { box-sizing: border-box; }
      h1 { font-size: 20px; margin: 0 0 4px; }
      .sub { color: #6B6558; font-size: 12px; margin-bottom: 18px; }
      .stats { display: flex; gap: 12px; margin: 16px 0 22px; }
      .card { border: 1px solid #E7E2D6; border-radius: 6px; padding: 10px 14px; flex: 1; }
      .card .label { font-size: 10.5px; color: #6B6558; }
      .card .num { font-size: 19px; font-weight: 700; margin-top: 2px; }
      h3 { font-size: 13px; margin: 22px 0 8px; border-left: 3px solid #BA7517; padding-left: 8px; }
      table { width: 100%; border-collapse: collapse; font-size: 11px; }
      th, td { border: 1px solid #E7E2D6; padding: 5px 8px; text-align: left; }
      th { background: #F3E4CC; }
    </style>
    <h1>두정테크 용접 불량 검출 리포트</h1>
    <div class="sub">대상 날짜: ${dateStr} · 생성 시각: ${new Date().toLocaleString("ko-KR")}</div>
    <div class="stats">
      <div class="card"><div class="label">총 검사</div><div class="num">${s.total}건</div></div>
      <div class="card"><div class="label">정상</div><div class="num">${s.good}건</div></div>
      <div class="card"><div class="label">불량</div><div class="num">${s.bad}건</div></div>
      <div class="card"><div class="label">평균 처리속도</div><div class="num">${s.avgMs}ms</div></div>
    </div>
    <h3>결함 유형별 건수</h3>
    <table><thead><tr><th>유형</th><th>건수</th></tr></thead><tbody>${defectRows}</tbody></table>
    <h3>검사 상세 목록 (${rows.length}건)</h3>
    <table>
      <thead><tr><th>ID</th><th>판정</th><th>결함 유형</th><th>신뢰도</th><th>처리속도</th><th>시각</th></tr></thead>
      <tbody>${detailRows}</tbody>
    </table>
  `;
  document.body.appendChild(container);

  try {
    const canvas = await html2canvas(container, { scale: 2, backgroundColor: "#ffffff" });
    const pdf = new jsPDF({ unit: "pt", format: "a4" });
    const pageW = pdf.internal.pageSize.getWidth();
    const pageH = pdf.internal.pageSize.getHeight();
    const imgW = pageW;
    const imgH = (canvas.height * imgW) / canvas.width;
    // JPEG로 인코딩 — 표/텍스트 위주 리포트라 PNG 대비 용량이 훨씬 작아지고(메일 첨부 등에 부담 없음), 화질 차이도 거의 안 보임
    const imgData = canvas.toDataURL("image/jpeg", 0.92);

    let heightLeft = imgH;
    let position = 0;
    pdf.addImage(imgData, "JPEG", 0, position, imgW, imgH);
    heightLeft -= pageH;
    while (heightLeft > 0) {
      position = heightLeft - imgH;
      pdf.addPage();
      pdf.addImage(imgData, "JPEG", 0, position, imgW, imgH);
      heightLeft -= pageH;
    }

    pdf.save(`두정테크_검사리포트_${dateStr}.pdf`);
  } finally {
    document.body.removeChild(container);
  }
}

