  const total = history.length;
  const totalPages = Math.ceil(total / pageSize);
  const start = (page - 1) * pageSize;
  const rows = history.slice(start, start + pageSize);

  const todayStr = new Date().toDateString();
  const yesterdayStr = new Date(Date.now() - 86400000).toDateString();
  const todayCount = history.filter(h => h.created_at.toDateString() === todayStr).length;
  const yestCount = history.filter(h => h.created_at.toDateString() === yesterdayStr).length;

  const formatCounts = REPORT_LOG_FORMATS.map(f => ({
    key: f, label: f.toUpperCase(),
    pct: total ? Math.round((history.filter(h => h.format === f).length / total) * 100) : 0,
  })).sort((a, b) => b.pct - a.pct);

  const completed = history.filter(h => h.status === "완료").length;
  const pending = total - completed;

