const IMAGE_EXT = /\.(jpg|jpeg|png|bmp|webp)$/i;

// Recursively walk a dropped folder's DataTransferItemList entries.
function readEntry(entry, path = "") {
  return new Promise((resolve) => {
    if (entry.isFile) {
      entry.file((file) => resolve([{ file, path: path + entry.name }]));
    } else if (entry.isDirectory) {
      const reader = entry.createReader();
      const all = [];
      const readBatch = () => {
        reader.readEntries(async (entries) => {
          if (!entries.length) {
            const nested = await Promise.all(all);
            resolve(nested.flat());
            return;
          }
          entries.forEach(e => all.push(readEntry(e, path + entry.name + "/")));
          readBatch();
        });
      };
      readBatch();
    } else {
      resolve([]);
    }
  });
}

function mockRunInspection(fileMeta, index) {
  let seed = fileMeta.path.split("").reduce((a, c) => a + c.charCodeAt(0), 0) + index * 17;
  const rand = () => { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; };
  const isBad = rand() < 0.25;
  return {
    id: `up-${index + 1}`,
    filename: fileMeta.path,
    ai_judgment: isBad ? "bad" : "good",
    defect_type: isBad ? DEFECT_TYPES[Math.floor(rand() * DEFECT_TYPES.length)] : null,
    confidence: 0.7 + rand() * 0.29,
    processing_time_ms: Math.round(38 + rand() * 70),
  };
}

